//
//  ExerciseAnimationCatalog.swift
//  Fernlet
//
//  Which approved exercise animation (revision r12, approved by the owner on 2026-10-29) belongs to
//  which bundled catalog exercise, and the generated still each one rests on. Custom exercises have
//  none and keep the demonstration tile they had.
//
//  `ExerciseAnimationCatalog.json` (generated by `Scripts/exercise-animation-catalog.py` from the
//  package) holds one row per bundled exercise; `ExerciseAnimationStills.bundle` holds the package's
//  398 stills byte for byte, one folder per character, because the file names repeat across the two.
//

import Foundation
import CoreGraphics
import ImageIO
import FernletDomainModel
import FernletFoundation

/// Which of the two approved characters draws an animation. It follows the profile's Sex setting:
/// female draws the female character, anything else the male one.
nonisolated enum ExerciseAnimationCharacter: String, CaseIterable, Sendable {
    case male
    case female

    /// The character for the profile's sex: female for `.female`, else male.
    init(sex: BiologicalSex) {
        self = sex == .female ? .female : .male
    }
}

/// One bundled exercise's approved animation: its stable ID in the animation package
/// (`exercise-NNN`), the loop length in seconds, whether it is a held pose, and the loop progress
/// its generated still shows.
nonisolated struct ExerciseAnimationEntry: Equatable, Sendable {
    /// The package's stable ID, `exercise-001` through `exercise-199`.
    let id: String
    /// The demonstration loop's length in seconds (not a workout prescription).
    let duration: Double
    /// A held pose: every progress draws the same frame.
    let hold: Bool
    /// The normalized progress (0...1) the generated still was rendered at.
    let stillProgress: Double
}

/// One row of `ExerciseAnimationCatalog.json`: the catalog exercise's exact name and equipment token
/// beside its animation's package fields.
nonisolated struct ExerciseAnimationCatalogRow: Codable, Equatable, Sendable {
    /// The exercise's name exactly as `WorkoutExercises.json` spells it.
    let name: String
    /// The exercise's `Equipment` raw value, as `WorkoutExercises.json` spells it.
    let equipment: String
    /// The package's stable ID, `exercise-NNN`.
    let id: String
    /// The demonstration loop's length in seconds.
    let duration: Double
    /// A held pose.
    let hold: Bool
    /// The normalized progress the generated still shows: 0.5 when animated, 0 for a hold.
    let stillProgress: Double

    /// The row's animation fields.
    var entry: ExerciseAnimationEntry {
        ExerciseAnimationEntry(id: id, duration: duration, hold: hold, stillProgress: stillProgress)
    }
}

/// The approved animations this build carries, looked up by the exercise's catalog name.
nonisolated enum ExerciseAnimationCatalog {
    /// The catalog's bundle resource name (`ExerciseAnimationCatalog.json`).
    static let catalogResource = "ExerciseAnimationCatalog"
    /// The stills' bundle directory name (`ExerciseAnimationStills.bundle`).
    static let stillsBundleResource = "ExerciseAnimationStills"

    /// Every entry, keyed by `WorkoutExerciseCatalog.normalizedName` of the exercise's name. Loaded
    /// once; empty (and logged) when the build's JSON is missing or unreadable.
    static let entries: [String: ExerciseAnimationEntry] = loadEntries()

    /// The animation for `exerciseName` (matched through `WorkoutExerciseCatalog.normalizedName`),
    /// or nil for a custom exercise.
    static func entry(forExerciseName exerciseName: String) -> ExerciseAnimationEntry? {
        entries[WorkoutExerciseCatalog.normalizedName(exerciseName)]
    }

    /// The generated still for `entry` drawn by `character`, or nil when the build lacks it.
    static func still(for entry: ExerciseAnimationEntry, character: ExerciseAnimationCharacter) -> CGImage? {
        guard let url = stillURL(for: entry, character: character),
              let source = CGImageSourceCreateWithURL(url as CFURL, nil) else { return nil }
        return CGImageSourceCreateImageAtIndex(source, 0, nil)
    }

    /// The still's path inside `ExerciseAnimationStills.bundle`, e.g. `female/exercise-086.png`.
    static func stillPath(for entry: ExerciseAnimationEntry, character: ExerciseAnimationCharacter) -> String {
        "\(character.rawValue)/\(entry.id).png"
    }

    /// The still's file URL in `bundle`, or nil when the build does not carry it (list rows can hand
    /// this to an image loader without decoding here).
    static func stillURL(for entry: ExerciseAnimationEntry, character: ExerciseAnimationCharacter,
                         in bundle: Bundle = .main) -> URL? {
        guard let stills = bundle.url(forResource: stillsBundleResource, withExtension: "bundle") else {
            return nil
        }
        let url = stills.appendingPathComponent(stillPath(for: entry, character: character))
        return FileManager.default.fileExists(atPath: url.path) ? url : nil
    }

    /// Decodes the catalog's JSON. Shared with the tests, which decode the committed file.
    static func decodeRows(_ data: Data) throws -> [ExerciseAnimationCatalogRow] {
        try JSONDecoder().decode([ExerciseAnimationCatalogRow].self, from: data)
    }

    /// Keys `rows` by normalized name; a repeated name keeps its first row.
    static func keyed(_ rows: [ExerciseAnimationCatalogRow]) -> [String: ExerciseAnimationEntry] {
        var keyed: [String: ExerciseAnimationEntry] = [:]
        for row in rows {
            let key = WorkoutExerciseCatalog.normalizedName(row.name)
            if keyed[key] == nil { keyed[key] = row.entry }
        }
        return keyed
    }

    private static func loadEntries() -> [String: ExerciseAnimationEntry] {
        // Unlike the Gym Visual media, this JSON ships in every build: missing is a broken build, so
        // both missing and unreadable leave a trace. The recovery is the old tile everywhere.
        guard let url = Bundle.main.url(forResource: catalogResource, withExtension: "json") else {
            FernletAuditLog.log("exercise.animations.catalog.missing")
            return [:]
        }
        do {
            return keyed(try decodeRows(Data(contentsOf: url)))
        } catch {
            FernletAuditLog.log("exercise.animations.catalog.load.failed",
                                context: ["error": error.localizedDescription])
            return [:]
        }
    }
}
